// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision resolution (D1–D4) -------------------------------------

// Sweeps the ball box from `prev` to its current position against one brick
// (the brick expanded by the ball radius, swept point vs box). Returns the
// earliest contact `{ t, face }` in [0, 1], or null. `t = 0` means the ball
// already overlapped the brick at the start of the pass: the face is then
// derived from the minimum-translation rule (discrete resolution).
// `face` is 'x' (side face), 'y' (top/bottom face) or 'both' (corner).
function sweptHit(prev, ball, brick) {
  const ex = brick.x - ball.r;
  const ey = brick.y - ball.r;
  const ew = brick.w + 2 * ball.r;
  const eh = brick.h + 2 * ball.r;
  const px = prev.x;
  const py = prev.y;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  // Overlapping at the start of the pass: discrete resolution. The face is the
  // axis of smallest penetration; equal penetrations mean a corner.
  if (px >= ex && px <= ex + ew && py >= ey && py <= ey + eh) {
    const penL = ball.x + ball.r - brick.x;
    const penR = brick.x + brick.w - (ball.x - ball.r);
    const penT = ball.y + ball.r - brick.y;
    const penB = brick.y + brick.h - (ball.y - ball.r);
    const penX = Math.min(penL, penR);
    const penY = Math.min(penT, penB);
    const face = penX < penY ? 'x' : penY < penX ? 'y' : 'both';
    return { t: 0, face, penL, penR, penT, penB, penX, penY };
  }

  // Slab sweep: entry/exit times on each axis.
  let tEnter = 0;
  let tExit = 1;
  let entryX = -Infinity;
  let entryY = -Infinity;

  if (dx === 0) {
    if (px <= ex || px >= ex + ew) return null; // parallel, never overlaps
  } else {
    let t1 = (ex - px) / dx;
    let t2 = (ex + ew - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    entryX = t1;
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (py <= ey || py >= ey + eh) return null; // parallel, never overlaps
  } else {
    let t1 = (ey - py) / dy;
    let t2 = (ey + eh - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    entryY = t1;
    if (tEnter > tExit) return null;
  }

  if (tEnter >= tExit || tEnter < 0 || tEnter > 1) return null;

  // The face entered last is the first one contacted; equal times = corner.
  const face = entryX > entryY ? 'x' : entryY > entryX ? 'y' : 'both';
  return { t: tEnter, face };
}

// Resolves the ball against every live brick for the current pass: kills and
// scores each touched brick, then applies ONE bounce per axis (earliest/deepest
// contact wins) and pushes the ball out of the rectangle. `prev` is the ball
// position at the start of the pass — required so a fast step that would jump
// cleanly over a brick still counts as a hit (no tunneling, no double flip).
export function resolveBrickCollisions(state, prev) {
  const { ball } = state;
  let best = null;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptHit(prev, ball, brick);
    if (!hit) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    if (!best || hit.t < best.hit.t) {
      best = { brick, hit };
    } else if (hit.t === best.hit.t) {
      // Same contact time (e.g. a grid seam): the deepest penetration leads.
      const depth = hit.penX + hit.penY;
      const bestDepth = best.hit.penX + best.hit.penY;
      if (depth > bestDepth) best = { brick, hit };
    }
  }

  if (!best) return;
  const { brick, hit } = best;

  // Bounce: the axis of the touched face; a corner flips both axes.
  if (hit.face === 'x' || hit.face === 'both') ball.vx = -ball.vx;
  if (hit.face === 'y' || hit.face === 'both') ball.vy = -ball.vy;

  if (hit.t > 0) {
