export function resolveBrickCollisions(state, prev) {
  const { ball } = state;
  const mvx = ball.x - prev.x;
  const mvy = ball.y - prev.y;

  // Collect every live brick touched by the swept ball box this pass.
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptHit(prev, ball, brick);
    if (hit) hits.push({ brick, hit });
  }
  if (hits.length === 0) return;

  // Earliest contact leads the bounce; on a tie (grid seam) the deepest
  // penetration leads. One bounce per pass per axis follows from resolving
  // a single contact.
  let best = hits[0];
