edits.newText:
// Paddle: the ball bounces when its bottom crosses the top edge during this
// pass (or still sits inside the band) while its center is over the paddle.
// Testing the crossed segment — not just the landing band — stops a fast
// step that jumps the whole 12 px band from tunneling through the paddle.
const inBand = ball.y + ball.r >= paddle.y && ball.y + ball.r <= paddle.y + paddle.h;
const crossedTop = prevBottom <= paddle.y && ball.y + ball.r >= paddle.y;
if (
  ball.vy > 0 &&
  (inBand || crossedTop) &&
  ball.x >= paddle.x &&
  ball.x <= paddle.x + paddle.w
) {
  ball.y = paddle.y - ball.r;
  // Exit angle from the hit offset (-1..1), clamped to a minimum deflection
  // (a dead-center hit still leaves at 30°), with the speed renormalized to
  // the level speed instead of rewriting vx alone.
  const speed = ballSpeed(state.level);
  const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
  const vx = speed * 0.6 * Math.max(Math.abs(hit), 0.5);
  ball.vx = (hit >= 0 ? 1 : -1) * vx;
  ball.vy = -Math.sqrt(speed * speed - vx * vx);
  state.combo = 0; // touching the paddle resets the combo
}

